(()=>{(function(){"use strict";document.addEventListener("click",o=>{let t=o.target.closest("[data-tui-dropdown-item]");if(!t||t.hasAttribute("data-tui-dropdown-submenu-trigger")||t.getAttribute("data-tui-dropdown-prevent-close")==="true")return;let e=t.closest("[data-tui-popovernative-root]")?.querySelector(":scope > [data-tui-popovernative-content]");if(e?.matches(":popover-open"))try{e.hidePopover()}catch{}})})();})();
